cd /workspace/src/Backend/Lecos.Strassennamen.RestAPI; cp appsettings.Development.json /tmp/appsettings.Development.json.orig; cat > appsettings.Development.json <<'EOF'
{
  "Serilog": {
    "Using":  [ "Serilog.Sinks.File" ],
    "MinimumLevel": {
      "Default": "Information",
      "Override": {
        "Microsoft.AspNetCore": "Information",
        "Microsoft.EntityFrameworkCore": "Warning",
        "System.Net.Http": "Warning"
      }
    },
    "WriteTo": [
      {
        "Name": "File",
        "Args": {
          "path": "Logs/log-.txt",
          "rollingInterval": "Day",
          "retainedFileCountLimit": "60"
        }
      }
    ]
  },
  "Logging": {
    "LogLevel": {
      "Default": "Debug",
      "Microsoft.EntityFrameworkCore.Database.Command": "Warning"
    }
  },
  "Keycloak": {
    "Realm": "my-realm",
    "AuthServerUrl": "http://localhost:8080/",
    "SslRequired": "none",
    "Resource": "strassennamen",
    "PublicClient": true,
    "VerifyTokenAudience": false,
    "ConfidentialPort": 0,
    "ClientName": "strassennamen"
  },
  "CorsOrigins": [
    "http://localhost:4200"
  ],
  "ConnectionStrings": {
    "DB": "Server=localhost,1433;Database=Strassennamen;User Id=sa;Password=Strassen!Passw0rd;TrustServerCertificate=true"
  },
  "Jobs": {
    "Heartbeat": {
      "Active": true,
      "CronSchedule": "0 0/5 * 1/1 * ? *"
    },
    "XmlExportStrassen": {
      "Active": false,
      "CronSchedule": "0 0 1 1/1 * ? *",
      "FilePath": "Export/strassen.xml",
      "FilterStrassenStatus": "Aktiv"
    }
  }
}
EOF
echo "written"; cat appsettings.Development.json | python3 -c "import json,sys; json.load(sys.stdin); print('valid json')"

